dslRule:
/*!id: replace.hardcoded.delay.with.openstrategy.postselectiondelay*/
/*!description: Replace hardcoded '500' delay value in specific JFace content assist controllers with OpenStrategy.getPostSelectionDelay().*/
/*!severity: INFO*/
new $Controller($creator, 500) :: (instanceof($Controller, "org.eclipse.jface.internal.text.link.contentassist.AdditionalInfoController2") || instanceof($Controller, "org.eclipse.jface.text.contentassist.AdditionalInfoController"))
=>
new $Controller($creator, org.eclipse.jface.util.OpenStrategy.getPostSelectionDelay())
;;

beforeExample:
package test;

import org.eclipse.jface.internal.text.link.contentassist.AdditionalInfoController2;
import org.eclipse.jface.text.contentassist.IInformationControlCreator;
import org.eclipse.jface.text.contentassist.AdditionalInfoController;

public class TestClass {
    IInformationControlCreator creator;

    void setup() {
        // Target 1
        AdditionalInfoController2 controller2 = new AdditionalInfoController2(creator, 500);

        // Target 2
        AdditionalInfoController controller = new AdditionalInfoController(creator, 500);

        // Not a target
        int someOtherValue = 500;
        System.out.println(500);
    }
}

afterExample:
package test;

import org.eclipse.jface.internal.text.link.contentassist.AdditionalInfoController2;
import org.eclipse.jface.text.contentassist.IInformationControlCreator;
import org.eclipse.jface.text.contentassist.AdditionalInfoController;
import org.eclipse.jface.util.OpenStrategy;

public class TestClass {
    IInformationControlCreator creator;

    void setup() {
        AdditionalInfoController2 controller2 = new AdditionalInfoController2(creator, OpenStrategy.getPostSelectionDelay());

        AdditionalInfoController controller = new AdditionalInfoController(creator, OpenStrategy.getPostSelectionDelay());

        int someOtherValue = 500;
        System.out.println(500);
    }
}

negativeExample:
package test;

import org.eclipse.jface.text.contentassist.IInformationControlCreator;
import org.eclipse.jface.util.OpenStrategy;

public class TestClass {
    IInformationControlCreator creator;

    void setup() {
        // Not a target: different constructor or different literal
        SomeOtherController otherController = new SomeOtherController(creator, 500);
        SomeOtherController otherController2 = new SomeOtherController(creator, 1000);

        // Already converted
        SomeOtherController otherController3 = new SomeOtherController(creator, OpenStrategy.getPostSelectionDelay());

        // Literal 500 not in the specified constructor context
        int x = 500;
        System.out.println("The value is " + 500);
    }

    static class SomeOtherController {
        SomeOtherController(IInformationControlCreator c, int delay) {}
    }
}
